
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_yt65_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_yt65", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.610318340164538e+01, 9.244540753190860e+01, 8.744379483830294e+01, 8.075414975374139e+01, 7.208547091261192e+01, 6.134828960255472e+01, 4.887513477802273e+01, 3.563741858170811e+01, 2.324211227516299e+01, 1.335264668896853e+01, 6.357778307754529e+00, 2.634370231248917e+00, 1.934146769914779e+00, 1.317211968209725e+00, 7.121654352958532e-01, 3.343125264080867e-01, 1.792225677178457e-01, 1.338563987595589e-01, 1.208908575705889e-01, 1.148722343590389e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


